pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 initialBal) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(initialBal > 0 && initialBal < type(uint256).max - 20);
        vm.deal(caller, 1 ether);
        vm.deal(other, 1 ether);

        // Set up other's balance by calling from other (requires other's balance == 0 initially)
        vm.prank(other);
        c.airDrop();
        uint256 otherBalBefore = c.tokenBalance(other);

        // Now caller tries to call airDrop (should revert after first call if balance != 0)
        vm.prank(caller);
        c.airDrop();

        uint256 otherBalAfter = c.tokenBalance(other);
        assertTrue(otherBalBefore == otherBalAfter);
    }
}

