pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(other != address(0) && caller != address(0));
        vm.assume(caller != address(0xC)); // avoid precompile address from failing vm.etch

        // Ensure only caller has zero balance - this is the precondition for airDrop to succeed
        vm.assume(c.tokenBalance(caller) == 0);

        // Ensure other address is not the caller
        vm.assume(other != caller);

        uint256 balanceBeforeOther = c.tokenBalance(other);

        vm.prank(caller);
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: if airDrop did not revert, then only the caller's balance changed (by exactly 20)
        // and no other address's balance changed.
        if (!reverted) {
            assertTrue(c.tokenBalance(caller) == 20);
            assertTrue(c.tokenBalance(other) == balanceBeforeOther);
        }
    }
}

