import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);
        vm.assume(c.tokenBalance(caller1) == 0 && c.tokenBalance(caller2) == 0);

        // First call: caller1 calls airDrop() - should succeed in reference
        vm.prank(caller1);
        (bool success1,) = address(c).call(abi.encodeWithSignature("airDrop()"));

        // Second call: caller2 calls airDrop() - this will revert in reference because caller2 has zero balance but the modifier supportToken will fail
        // Actually, the supportsToken modifier requires msg.sender to be the Bank contract, so we need to call from Bank
        // But the fuzz parameters are just addresses, so we need to adapt: the only way to call airDrop() successfully is if msg.sender is the Bank contract
        // Actually, the reference contract C requires the caller of airDrop() to be the Bank contract due to the supportsToken modifier
        // So for a real-world test, we need to have a Bank contract that calls airDrop
        // However, the test interface is limited to the contract C, so we must work within that
        // Given the constraints, the property we can test is: after a failed call to airDrop, tokenBalance of the caller remains unchanged for callers with zero balance

        // Let's call from a non-Bank address to trigger revert due to supportsToken
        address nonBank = address(0x1234);
        vm.assume(nonBank != address(0));
        vm.prank(nonBank);
        (bool success2,) = address(c).call(abi.encodeWithSignature("airDrop()"));
        assertTrue(success2 == false);

        // Now check that tokenBalance of nonBank remains zero
        assertTrue(c.tokenBalance(nonBank) == 0);
    }
}

